import pandas as pd

def clean(df):
    df = df.copy()
    # Convert columns that are stored as text numbers to numeric
    for col in ["flipper_length_mm", "body_mass_g", "year", "bill_length_mm", "bill_depth_mm"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")
    # Fix sex label variant with extra spaces
    if "sex" in df.columns:
        df["sex"] = df["sex"].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # Fix island label variant
    if "island" in df.columns:
        df["island"] = df["island"].replace({"Bisco": "Biscoe"})
    # Remove exact duplicate rows
    df = df.drop_duplicates(keep="first")
    return df

def answer(df):
    dfc = clean(df)
    # Average body mass per sex, ignoring missing sex
    means = dfc.groupby("sex", dropna=False)["body_mass_g"].mean()
    result = {}
    for sex, val in means.items():
        if pd.notna(sex) and pd.notna(val):
            result[str(sex)] = float(val)
    return result
